/*
 * A285302  Positions of 0 in A285301, complement of A086398.
 * https://oeis.org/A285302
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = n-th positive integer not in A086398 (complement);
 *            A086398 generated by its recurrence b(1)=1, b(k)=b(k-1)+2, or +4
 *            if k not a term but k-1 is
 * Range:     u8 n <= 162, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 81 terms through n = 9184 (2026-11-08)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;
    size_t L = (size_t)n * 2 + 16;
    unsigned char *in = (unsigned char *)calloc(L + 2, 1);
    if (!in) exit(EXIT_FAILURE);
    size_t b = 1;
    in[1] = 1;
    for (size_t k = 2; k <= L; k++) {
        size_t inc = 2;
        if (!in[k] && in[k - 1]) inc = 4;
        b += inc;
        if (b > L) break;
        in[b] = 1;
    }
    size_t cnt = 0, res = 0;
    for (size_t i = 1; i <= L; i++) {
        if (!in[i]) {
            cnt++;
            if ((idx_t)cnt == n) { res = i; break; }
        }
    }
    free(in);
    return (seq_t)res;
}
